public class OwnedCursorShell64 {
 public virtual class View {
  protected Database.Cursor handle;
  protected View(Database.Cursor value) { handle=value; }
  public Database.Cursor getHandle() { return handle; }
  public virtual List<Account> page() { return new List<Account>(); }
  public virtual Integer size() { return 0; }
 }
 public class LocalView extends View {
  private List<Account> localRows;
  public LocalView(Database.Cursor value,List<Account> rows) { super(value); localRows=rows; }
  public override List<Account> page() { return localRows; }
  public override Integer size() { return localRows.size(); }
 }
}
